//! Copies the token table generated by Nix into `OUT_DIR`.
//!
//! The tokens are defined in `assets/tokens/*.nix` and generated by
//! `nix/scripts/gen-tokens.py`. This build script does NOT generate them — it only
//! locates the finished file. Generating here would be reimplementing Nix logic
//! (invariant 5) and would leave the source of truth.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_TOKENS_RS");

    let generated = env::var("RONOCTUA_TOKENS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_TOKENS_RS nao esta definida.\n\
             \n\
             A tabela de tokens e gerada pelo Nix a partir de assets/tokens/*.nix.\n\
             Entre no ambiente com `direnv allow` (ou `nix develop`), que define\n\
             a variavel, ou construa pelo flake com `nix build`.\n\
             \n\
             Gerar os tokens aqui seria reimplementar logica Nix (invariante 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("tokens.rs");
    // DELETE FIRST. The file comes from the store, and `fs::copy` inherits the
    // read-only mode along with the content: on the second token generation the
    // destination already exists without write permission and the copy fails with
    // "Permission denied", inside a build.rs — far from anything the
    // person has just edited. It is the trap recorded in CLAUDE.md.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("nao consegui copiar {generated} -> {destination:?}: {e}"));
}
